Sure, let's create a script that takes a list of words and dynamically places input fields where there are spaces in the sentence. The script will then check if the sentence is correct when the user finishes entering the text.

Here's the updated script:

### Script:

```c#
using System;
using System.Collections.Generic;
using Screens.Bases;
using TMPro;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using ColorUtility = UnityEngine.ColorUtility;

namespace Screens
{
    public class Screen8StringCheck : ScreenBase
    {
        [SerializeField] private GameObject inputFieldPrefab;
        [SerializeField] private GameObject textPrefab;
        [SerializeField] private Transform inputFieldParent;
        [SerializeField] private List<string> words;
        [SerializeField] private GameObject failedGO;

        private List<InputField> inputFields = new List<InputField>();
        private List<string> correctWords = new List<string>();

        protected override void Start()
        {
            Init();
        }

        private void Init()
        {
            base.Start();

            foreach (var word in words)
            {
                if (string.IsNullOrEmpty(word))
                {
                    continue;
                }

                if (word == " ")
                {
                    // Instantiate input field prefab
                    GameObject inputFieldGO = Instantiate(inputFieldPrefab, inputFieldParent);
                    InputField inputField = inputFieldGO.GetComponent<InputField>();
                    inputField.characterLimit = 1;
                    inputField.onValueChanged.AddListener(delegate { OnFieldValueChanged(); });
                    inputField.onEndEdit.AddListener(delegate { OnFieldValueChanged(); });
                    inputFields.Add(inputField);
                    correctWords.Add(word);
                }
                else
                {
                    // Instantiate text prefab
                    GameObject textGO = Instantiate(textPrefab, inputFieldParent);
                    Text textComponent = textGO.GetComponent<Text>();
                    textComponent.text = word;
                    correctWords.Add(word);
                }
            }
        }

        private void OnFieldValueChanged()
        {
            IsSentenceCorrect();
        }

        private void IsSentenceCorrect()
        {
            int inputFieldIndex = 0;
            bool isSentenceCorrect = true;

            for (int i = 0; i < correctWords.Count; i++)
            {
                if (correctWords[i] == " ")
                {
                    if (inputFields[inputFieldIndex].text != correctWords[i])
                    {
                        isSentenceCorrect = false;
                    }
                    inputFieldIndex++;
                }
            }

            if (isSentenceCorrect)
            {
                DeactivateFailedMessage();
                EventManager.AssignmentCompleted.Invoke();
            }
            else
            {
                ActivateFailedMessage();
            }
        }

        private void DeactivateFailedMessage()
        {
            failedGO.SetActive(false);
            // Change color of input fields
            foreach (InputField inputField in inputFields)
            {
                inputField.image.color = Color.white;
            }
        }

        private void ActivateFailedMessage()
        {
            failedGO.SetActive(true);
            foreach (InputField inputField in inputFields)
            {
                bool parseSuccess = ColorUtility.TryParseHtmlString("#FF4050", out Color newCol);
                inputField.image.color = newCol;
            }
        }
    }
}
```

### Steps to Use the Script:

1. **Create an InputField Prefab:**
   - In your Unity project, create a new `GameObject`.
   - Add an `InputField` component to this `GameObject`.
   - Customize the `InputField` as needed (e.g., set the font, size, etc.).
   - Save this `GameObject` as a prefab (e.g., `InputFieldPrefab`).

2. **Create a Text Prefab:**
   - In your Unity project, create a new `GameObject`.
   - Add a `Text` component to this `GameObject`.
   - Customize the `Text` as needed (e.g., set the font, size, etc.).
   - Save this `GameObject` as a prefab (e.g., `TextPrefab`).

3. **Set Up the Scene:**
   - Create an empty `GameObject` in your scene to act as the parent for the input fields and text elements (e.g., `InputFieldParent`).
   - Add the `Screen8StringCheck` script to a `GameObject` in your scene (e.g., an empty `GameObject` named `ScreenManager`).

4. **Assign the Prefabs and Parent in the Inspector:**
   - Select the `GameObject` with the `Screen8StringCheck` script (e.g., `ScreenManager`).
   - In the Inspector, you will see the fields for `InputFieldPrefab`, `TextPrefab`, `InputFieldParent`, `Words`, and `FailedGO`.
   - Drag and drop the `InputFieldPrefab` into the `InputFieldPrefab` field.
   - Drag and drop the `TextPrefab` into the `TextPrefab` field.
   - Drag and drop the `InputFieldParent` into the `InputFieldParent` field.
   - Set the `Words` field to the list of words you want to use, with spaces represented by the string " ".
   - Assign the `FailedGO` field to the `GameObject` that should be activated when the input is incorrect.

