        {
            base.Start();

            if (inputFieldPrefab == null)
            {
                Debug.LogError("inputFieldPrefab is not assigned.");
                return;
            }

            if (textPrefab == null)
            {
                Debug.LogError("textPrefab is not assigned.");
                return;
            }

